{"description":"Solve two-point with careful guards","cmd":"python3 - <<'PY'
import numpy as np, math
from scipy.optimize import root, least_squares
N=150000; logN=math.log(N); target=logN-10

def eqs(v):
    q,r=v
    if not (0<q<1 and r>0 and q*r<1):
        return [1e6, 1e6]
    s=(1-q*r)/(1-q)
    if s<=0:
        return [1e6, 1e6]
    e1=q*math.log(r)+(1-q)*math.log(s)+10
    e2=q*r*math.log(r)+(1-q)*s*math.log(s)-target
    return [e1,e2]

for k in range(1,21):
  q0=k/N
  for r0 in [N/k*0.5, N/k*0.8, N/k, N/k*1.2, N/k*1.5]:
    if not (q0*r0<1): continue
    try:
      res = least_squares(eqs, [q0,r0], bounds=([1e-12,1.0],[0.5,N*10]), max_nfev=5000)
      qq,rr=res.x; ss=(1-qq*rr)/(1-qq)
      if res.cost < 1e-18:
        print('LS k',k,'init r',r0,'=> q',qq,'r',rr,'s',ss,'res',eqs([qq,rr]),'k_eff',qq*N)
    except Exception as e:
      print('LS err',k,r0,e)
print('done')
