{"description":"Evaluate two-point residuals across k and r","cmd":"python3 - <<'PY'
import numpy as np, math
N=150000; logN=math.log(N); target=logN-10

def residuals(q,r):
    if not (0<q<1 and r>0 and q*r<1):
        return (None,None)
    s=(1-q*r)/(1-q)
    if s<=0: return (None,None)
    return (q*math.log(r)+(1-q)*math.log(s)+10, q*r*math.log(r)+(1-q)*s*math.log(s)-target)

for k in range(1,16):
  q=k/N
  best=None
  for r in np.geomspace(N/(k+0.5), N/(max(k-0.5,0.1)), 1001):
    e1,e2=residuals(q,r)
    if e1 is not None:
      score=abs(e1)+abs(e2)
      if best is None or score<best[0]: best=(score,e1,e2,r)
  if best:
    print('k',k,'best',best)
