{"description":"Solve three-level distribution with various k,m","cmd":"python3 - <<'PY'
import numpy as np, math
from scipy.optimize import root, least_squares
N=150000

def equations(v,k,m):
    A,B,E=v
    l=N-k-m
    if min(A,B,E)<=0 or l<=0:
        return np.array([1e9,1e9,1e9])
    eq1 = k*A + m*B + l*E - N
    eq2 = (k*A*math.log(A) + m*B*math.log(B) + l*E*math.log(E)) - 10*N
    eq3 = (k*math.log(A) + m*math.log(B) + l*math.log(E)) + 10*N
    return np.array([eq1,eq2,eq3])

best=(1e9,None)
for k in range(1,16):
  for m in range(1,25):
    if m==k: continue
    l=N-k-m
    if l<=0: continue
    guesses=[
        (N/k, N/m, math.exp(-10)),
        (N/k, N/(k+m), math.exp(-10)),
        (N/k*0.9, N/m*1.1, math.exp(-8)),
        (N/k, N/m*0.5, math.exp(-9)),
    ]
    for g in guesses:
      try:
        sol=root(equations, g, args=(k,m), method='lm')
        if sol.success and np.max(np.abs(equations(sol.x,k,m)))<1e-5:
          res=equations(sol.x,k,m)
          A,B,E=sol.x; l=N-k-m
          print('SOLVED k,m',k,m,'A,B,E',sol.x,'res',res,'tail total mass',l*E/N)
      except Exception: pass
print('done; best',best[0],best[1])
PY"}
